/** @param {NS} ns */
export async function main(ns) {
    let servers = await ns.scan('home');
    let targetServer = null;
    let maxSecurityToMoneyRatio = -Infinity;

    for (let server of servers) {
        let security = await ns.getServerSecurityLevel(server);
        let money = await ns.getServerMaxMoney(server);
        if (security > 0 && money > 0) {
            let ratio = security / money;
            if (ratio < maxSecurityToMoneyRatio) {
                maxSecurityToMoneyRatio = ratio;
                targetServer = server;
            }
        }
    }

    if (targetServer) {
        await ns.hack(targetServer);
        let gainedMoney = await ns.getServerMaxMoney(targetServer) - await ns.getServerMoneyAvailable(targetServer);
        ns.tprint(`Gained ${gainedMoney} from ${targetServer}`);
    } else {
        ns.tprint('No servers available to hack.');
    }
}

